// resolveLocalConnectorBindings maps one render's fixture choices to the local
// environment. They are never persisted outside that render.
func resolveLocalConnectorBindings(ctx context.Context, opts manifestRunOptions, facts manifestFacts, lib *template.Library) (map[string]map[string]string, error) {
	fixtures, err := fixtureCatalog(lib)
	if err != nil {
		return nil, err
	}
	if len(fixtures) == 0 {
		return nil, missingBindingCatalog(lib.Ref(), "fixture", "spec.local.fixtures", TemplateDeployComponent)
	}
	choices, err := resolveConnectorBindingChoices(ctx, opts, facts, fixtures, "local", "fixture")
	if err != nil {
		return nil, err
	}
	return bindChoicesToEnvironments(choices, []string{localEnv}), nil
}

// resolveGitOpsConnectorBindings maps binding choices to every GitOps
// environment rendered by create. Local rendering resolves its own choices,
// so the two commands cannot affect one another.
func resolveGitOpsConnectorBindings(ctx context.Context, opts manifestRunOptions, facts manifestFacts, lib *template.Library) (map[string]map[string]string, error) {
	kinds, err := gitOpsBindingCatalog(lib)
	if err != nil {
		return nil, err
	}
	if len(kinds) == 0 {
		return nil, missingBindingCatalog(lib.Ref(), "GitOps binding", "spec.gitops.bindingKinds", TemplateDeployHost)
	}
	choices, err := resolveConnectorBindingChoices(ctx, opts, facts, kinds, "GitOps", "kind")
	if err != nil {
		return nil, err
	}
	return bindChoicesToEnvironments(choices, facts.Environments), nil
}

// resolveConnectorBindingChoices validates explicit kinds and asks for the
// missing ones. Its callers deliberately supply distinct local and GitOps
// catalogs, so the two commands have no shared binding configuration.
func resolveConnectorBindingChoices(ctx context.Context, opts manifestRunOptions, facts manifestFacts, catalog []string, target, valueLabel string) (map[string]string, error) {
	explicit, err := parseConnectorBindingArgs(opts.Bindings)
	if err != nil {
		return nil, err
	}
	connectors := make(map[string]ManifestConnector, len(facts.Model.Connectors))
	for _, connector := range facts.Model.Connectors {
		connectors[connector.Name] = connector
	}
	for _, name := range slices.Sorted(maps.Keys(explicit)) {
		binding := explicit[name]
		if _, ok := connectors[name]; !ok {
			return nil, fmt.Errorf("--binding names connector %q, which the topology does not declare", name)
		}
		if !slices.Contains(catalog, binding) {
			return nil, fmt.Errorf("connector %s uses unsupported %s %q; available %ss: %s", name, valueLabel, binding, valueLabel, strings.Join(catalog, ", "))
		}
	}

	choices := make(map[string]string, len(facts.Model.Connectors))
	var missing []string
	for _, connector := range facts.Model.Connectors {
		binding := explicit[connector.Name]
		if binding == "" && opts.Selector != nil {
			binding, err = selectConnectorBinding(ctx, opts.Selector, connector, catalog, target)
			if err != nil {
				return nil, fmt.Errorf("select %s binding for connector %s: %w", strings.ToLower(target), connector.Name, err)
			}
		}
		if binding == "" {
			missing = append(missing, connector.Name)
			continue
		}
		if !slices.Contains(catalog, binding) {
			return nil, fmt.Errorf("connector %s uses unsupported %s %q; available %ss: %s",
				connector.Name, valueLabel, binding, valueLabel, strings.Join(catalog, ", "))
		}
		choices[connector.Name] = binding
	}
	if len(missing) > 0 {
		return nil, fmt.Errorf("%s bindings are required for connectors: %s\npass one '--binding <connector>=<%s>' for each; available %ss: %s",
			strings.ToLower(target), strings.Join(missing, ", "), valueLabel, valueLabel, strings.Join(catalog, ", "))
	}
	return choices, nil
}

func bindChoicesToEnvironments(choices map[string]string, environments []string) map[string]map[string]string {
	resolved := make(map[string]map[string]string, len(choices))
	for connector, binding := range choices {
		perEnvironment := make(map[string]string, len(environments))
		for _, environment := range environments {
			perEnvironment[environment] = binding
		}
		resolved[connector] = perEnvironment
	}
	return resolved
}

func parseConnectorBindingArgs(args []string) (map[string]string, error) {
	bindings := make(map[string]string, len(args))
	for _, arg := range args {
		name, fixture, ok := strings.Cut(arg, "=")
		name, fixture = strings.TrimSpace(name), strings.TrimSpace(fixture)
		if !ok || name == "" || fixture == "" {
			return nil, fmt.Errorf("invalid --binding %q; use --binding <connector>=<fixture>", arg)
		}
		if _, duplicate := bindings[name]; duplicate {
			return nil, fmt.Errorf("--binding specifies connector %s more than once", name)
		}
		bindings[name] = fixture
	}
	return bindings, nil
}

